"""Explain semaphore grants, direct handoff, tracing and integer boundaries."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1529': ('가위가 없어 기다리던 친구의 카드에 “가위 전달함” 도장을 찍었다고 해 봅시다. 다시 활동할 차례가 오면 남은 시간보다 그 도장을 먼저 확인하는 길이 있습니다.', '잠들었다 돌아온 뒤 허가 전달 표시를 먼저 확인하는 순서를 이해합니다.', '등록 → 신호·시간 검사 → 잠금 풀고 기다림 → 잠금 다시 잡기 → up 표시 확인을 그리세요. up이 참이면 성공으로 나가는 화살표를 넣으세요.', ['___down_common은 허가가 없을 때 쓰는 공통 대기 코드입니다. 지역 공간인 스택에 waiter라는 대기 카드를 만듭니다. 카드에는 줄 연결 list, 기다리는 작업 주소 task, 허가를 받았는지 표시하는 up이 있습니다.', '잠금으로 보호된 상태에서 카드를 줄 끝에 넣고 task=current, up=false를 정합니다. current는 지금 실행 중인 작업이고 false는 아직 허가를 받지 않았다는 뜻입니다. 등록만 했다고 자원을 사용할 수 있는 것은 아닙니다.', '반복의 처음에는 허용된 신호를 보고 그다음 시간 만료를 봅니다. 나갈 이유가 없으면 작업을 대기 상태로 정하고 raw 잠금을 풉니다. schedule_timeout으로 기다린 뒤 다시 잠금을 잡습니다.', '돌아온 바로 그 자리에서는 waiter.up을 먼저 확인합니다. 참이면 허가를 전달받았으므로 성공 0을 반환합니다. 남은 시간이 0이거나 신호가 새로 왔어도 다음 반복의 신호·시간 검사보다 이 확인이 앞섭니다. 처음 진입의 검사 순서와 돌아온 뒤 순서를 나누어 보세요.', '깨웠다는 사실 자체가 성공 표시는 아닙니다. 허가를 주는 쪽이 up=true를 적어야 합니다. 표시가 거짓이면 다음 반복으로 가서 신호와 시간을 다시 확인합니다. 불러서 일어난 것과 가위를 받은 것은 다른 일입니다.', '허가 없이 신호나 시간 만료로 끝나면 자신의 카드를 list_del로 제거합니다. 허가를 받은 길에서는 전달하는 쪽이 이미 카드를 제거했습니다. 함수가 반환해 스택 자료를 더는 쓸 수 없게 된 뒤 줄에 오래된 카드 주소가 남지 않도록 하는 규칙입니다.'], [('기다렸다가 잠금을 다시 잡았어요. 성공을 먼저 확인하는 표시는?', ['남은 시간이 양수인지예요', '허가를 받았다는 waiter.up이에요'], '코드는 잠금을 다시 잡은 바로 다음에 if (waiter.up)을 봅니다. 참이면 성공 0으로 끝나요. 이때 시간이 0이어도 다음 반복의 만료 검사보다 허가 확인이 먼저입니다.'), ('허가를 받지 못하고 신호나 시간 만료로 끝나면 카드를 그대로 두나요?', ['아니요. 자기 항목을 목록에서 빼요', '네. 언젠가 다른 작업이 지울 때까지 남겨요'], '두 오류 출구에는 list_del이 있습니다. 지역 카드가 함수 종료 뒤에도 목록에 남으면 잘못된 주소 접근으로 이어질 수 있으므로 직접 정리합니다.')]), 'os1530': ('반납된 가위를 기다리는 친구가 있으면 그 친구에게 바로 건네고, 아무도 없으면 보관함에 넣는다고 해 봅시다. 직접 건넨 가위를 보관함의 남은 수에도 더하면 같은 가위를 두 번 센 셈이 됩니다.', '반환한 허가를 저장하는 길과 첫 대기자에게 직접 넘기는 길을 구별합니다.', 'count=0·줄 A → B에서 up을 하면 A의 표시=true, 줄 B, count=0을 적으세요. 빈 줄에서는 count가 하나 늘어나는 경우와 비교하세요.', ['up은 허가를 반환하는 함수입니다. 먼저 irqsave raw 잠금으로 count와 대기 줄을 보호합니다. 이 잠금 안에서 목록이 비었는지에 따라 두 길로 나뉩니다.', '줄이 비었다면 count++로 남은 허가 수를 하나 늘립니다. 지금 받을 작업이 없으므로 나중 획득자가 사용할 수 있게 저장하는 셈입니다. 예를 들어 count=2이면 3이 됩니다.', '대기자가 있으면 __up을 부릅니다. 이 내부 함수는 list_first_entry로 맨 앞 카드를 고릅니다. 등록은 끝에 하고 전달은 앞에서 하므로 정상적인 줄에서는 먼저 등록해 남아 있는 항목부터 선택합니다. 실제 작업 완료 순서까지 보장하는 말은 아닙니다.', '선택한 항목을 목록에서 제거하고 waiter.up=true를 적은 뒤 wake_up_process로 작업을 깨웁니다. 표시를 먼저 적어야 돌아온 작업이 허가를 받았다는 사실을 확인할 수 있습니다.', '이 전달 경로에는 count++가 없습니다. 이미 선택한 대기자에게 준 허가를 남은 공용 허가로 다시 올리지 않는 것입니다. 정상 사용에서 count=0, 줄 A → B라면 A에게 허가를 주고 count는 0, 줄은 B가 됩니다. 새 작업이 이 허가를 count에서 먼저 가져가는 길과 다릅니다.', 'up은 소유자 검사를 하지 않으므로 호출자가 반환 규칙을 지켜야 합니다. 빈 줄에서의 증가에는 최대값을 유지하는 포화 검사도 없습니다. 완료 알림 completion에서 본 특별한 최대값 규칙을 세마포어에도 있다고 가정하면 안 됩니다.'], [('기다리는 A에게 up으로 허가를 넘길 때 count도 먼저 하나 늘리나요?', ['네. 모든 up은 반드시 count를 늘려요', '아니요. A의 카드에 직접 허가 표시를 해요'], '대기자가 있으면 __up으로 가서 제거 → up=true → 깨움을 합니다. 이 길에는 count 증가가 없어요. 직접 준 허가를 공용 남은 수에도 올려 두 번 세지 않습니다.'), ('A → B → C가 기다릴 때 __up이 고르는 카드는?', ['첫 항목 A예요', '마지막에 등록된 C예요'], 'list_first_entry로 앞 항목을 고릅니다. 줄 끝 등록과 앞쪽 전달을 함께 보면 먼저 등록한 항목을 선택하는 순서를 이해할 수 있어요. 이후 CPU 실행과 실제 작업 종료 순서는 별도입니다.')]), 'os1531': ('줄에서 기다리기 전과 후에 기록 담당자가 “시작”, “성공 또는 중단”을 적는다고 해 봅시다. 기록은 무슨 일이 있었는지 관찰하는 일이며 가위를 나눠 주는 규칙 그 자체는 아닙니다.', '대기 알고리즘과 그 앞뒤 추적 기록을 구별합니다.', 'trace 시작 → 실제 대기 → 결과 ret → trace 끝에 ret 전달 → 같은 ret 반환을 그리세요. 결과에 0, -EINTR, -ETIME을 각각 넣어 보세요.', ['경합은 여러 작업이 같은 제한된 자원이나 잠금을 두고 경쟁하는 상황입니다. trace는 실행 중 사건을 관측하기 위한 추적 연결입니다. 실제로 어떤 기록이 수집되는지는 커널 설정과 추적 기능 활성화에 달려 있습니다.', '밑줄 두 개인 __down_common은 먼저 trace_contention_begin(sem, 0)을 부릅니다. 그다음 밑줄 세 개인 ___down_common을 실행해 실제 대기 결과를 ret라는 정수 칸에 받습니다. 비슷한 이름의 두 함수를 구별하세요.', '이후 trace_contention_end(sem, ret)로 같은 결과를 전달하고 return ret로 호출자에게 돌려줍니다. 성공이면 0, 해당 경로의 신호 중단이면 -EINTR, 시간 만료이면 -ETIME이 기록 지점에 전달됩니다. 초기 count를 결과 대신 보내는 것이 아닙니다.', '이 계측 wrapper 자체는 허가를 새로 주거나 반환 코드를 다른 의미로 바꾸지 않습니다. 실제 등록, 대기, 허가 확인과 목록 제거는 안쪽 공통 코드에서 수행합니다. 관측을 위한 코드와 상태를 바꾸는 핵심 코드를 나누면 흐름이 잘 보입니다.', '바깥 __down 계열은 공통 코드에 대기 상태와 시간을 전달합니다. 예를 들어 __down_killable은 TASK_KILLABLE, __down_timeout은 지정 시간을 줍니다. 공통 코드를 여러 규칙으로 재사용하는 방식입니다.', 'inline은 컴파일러가 함수 코드를 호출 위치에 펼쳐 최적화할 수 있게 하는 선언입니다. 원문은 그 과정에서 고정된 state나 timeout에 관한 조건 계산을 줄일 수 있다고 설명합니다. 선택한 신호 규칙을 무시하거나 모든 신호를 삭제한다는 뜻은 아닙니다. 추적 호출을 읽었다는 사실도 실제 커널의 대기 시간을 측정했다는 증거는 아닙니다.'], [('trace_contention_end에 어떤 값을 전달하나요?', ['언제나 처음 count만 전달해요', '실제 공통 대기가 돌려준 ret를 전달해요'], 'ret = ___down_common(...) 뒤에 trace_contention_end(sem, ret)가 있습니다. 성공이나 중단 결과를 관측하도록 연결한 것이며 초기 허가 수를 보내는 코드가 아닙니다.'), ('inline된 코드에서 고정 state를 안다는 것은 무엇에 도움이 되나요?', ['컴파일러가 상수 조건 계산을 줄이는 데 도움이 돼요', '모든 신호를 자동 삭제해 기다림 규칙을 없애요'], '컴파일은 코드를 실행할 형태로 번역하는 단계입니다. 이미 아는 인자를 이용해 불필요한 계산을 줄일 수 있지만 선택한 상태의 동작 약속까지 없애는 것은 아닙니다.')]), 'os1532': ('칸이 한정된 숫자판을 생각해 봅시다. 0부터 9까지만 있는 한 자리 판에서 9 다음을 다시 0으로 돌리는 규칙이 있을 수 있습니다. 컴퓨터 정수도 담을 수 있는 범위와 넘었을 때의 규칙을 알아야 합니다.', 'unsigned 계산과 int 변환을 단계로 나누고 큰 경계값을 정상 사용과 구별합니다.', '32비트 예시에서 INT_MAX=2147483647을 적으세요. 2147483649 - 1 = 2147483648 다음 signed 해석 -2147483648, 실패 1의 순서를 따라 쓰세요.', ['세마포어의 sem->count는 unsigned int입니다. unsigned는 음수를 표현하지 않는다는 뜻입니다. down_trylock의 지역 변수 count는 int라 음수를 표현할 수 있습니다. 저장 칸과 임시 칸의 표현 범위가 다릅니다.', 'count = sem->count - 1에서는 먼저 unsigned 뺄셈을 하고 그 결과를 int에 넣습니다. 작은 정상 허가 수에서는 이해하기 쉽지만 아주 큰 값을 넣으면 “원래 양수였으니 성공”이라는 추측이 맞지 않을 수 있습니다.', '여기서는 unsigned와 int가 32비트이고 결과 비트열을 2의 보수 signed 값으로 해석하는 구성의 계산 예시를 사용합니다. INT_MAX는 2147483647입니다. 그보다 2 큰 2147483649에서 1을 빼면 unsigned 결과는 2147483648입니다.', '이 비트열을 그 구성의 int로 해석하면 -2147483648이 됩니다. 따라서 count >= 0이 거짓이라 원래 sem->count를 갱신하지 않고, count < 0이 참이라 실패 1을 반환합니다. 모든 C 구현의 범위 밖 signed 변환 결과까지 같다고 일반화하는 예시는 아닙니다.', '빈 대기 줄에서 up은 sem->count++만 수행합니다. unsigned의 최대값 UINT_MAX에 하나를 더하면 0으로 돌아갑니다. 32비트 예시라면 4294967295 다음이 0입니다. completion처럼 최대값에서 증가를 멈추는 조건문은 이 경로에 없습니다.', '이것은 잘못된 큰 값이나 균형을 잃은 반환을 이해하기 위한 경계 연습입니다. 실제 학습 코드에서 세마포어 멤버를 직접 바꾸라는 사용법이 아닙니다. 호출자는 유효한 자원 수와 획득·반환의 대응을 유지해야 하며 숫자판의 범위가 자원 사용 규칙을 대신해 주지 않습니다.'], [('위 32비트 예시에서 sem->count=INT_MAX+2라면 trylock 결과는?', ['원래 값이 양수이므로 모든 구성에서 반드시 성공해요', '실패 1이고 원래 저장된 count는 유지돼요'], 'unsigned 뺄셈 뒤 int 임시 값이 이 예시에서는 음수가 됩니다. 갱신 조건을 통과하지 못하므로 저장 값은 유지되고 실패 1이에요. 변환을 생략해 생각하면 틀립니다.'), ('줄이 비고 count=UINT_MAX일 때 up이 최대값을 그대로 유지하나요?', ['아니요. unsigned 증가로 0으로 돌아가요', '네. completion처럼 최대값 검사가 있어요'], '이 분기는 count++이며 포화 검사가 없습니다. unsigned 최대값을 넘으면 0으로 돌아가는 규칙을 따릅니다. 다른 도구에 있던 최대값 보호를 여기에도 있다고 생각하면 안 됩니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_378.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
